/** Giải mã một file âm thanh mẫu thành Blob (null nếu không có). */
export function sampleAudioBlob(file: string): Blob | null {
  const b64 = SAMPLE_AUDIO_BASE64[file];
  if (!b64) return null;
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new Blob([bytes], { type: "audio/mpeg" });
}
